// MISTAKE: God class doing everything
class ParkingLotManager {
    void assignSpot(Vehicle v) { /* allocation logic */ }
    void processPayment(Ticket t) { /* payment logic */ }
    void generateReport() { /* reporting logic */ }
    void sendNotification(String msg) { /* notification logic */ }
}

// BETTER: Single Responsibility per class
class SpotAllocator {
    ParkingSpot findAvailableSpot(VehicleType type) {
        // Allocation strategy goes here
        return spots.stream()
            .filter(s -> s.getType() == type && s.isAvailable())
            .findFirst().orElse(null);
    }
}

class PaymentProcessor {
    Receipt processPayment(Ticket ticket, PaymentMethod method) {
        var amount = calculateFee(ticket);
        // Payment gateway interaction
        return new Receipt(ticket.getId(), amount);
    }
}

class ReportGenerator {
    DailyReport generate(LocalDate date) {
        // Aggregates stats from repository
        return new DailyReport(date, occupancyRate, revenue);
    }
}

// Original design with extension point
abstract class ParkingSpot {
    private String id;
    private SpotStatus status;
    private VehicleType supportedType;

    abstract boolean canAccommodate(Vehicle vehicle);
    abstract double calculateHourlyRate();
}

class StandardSpot extends ParkingSpot {
    boolean canAccommodate(Vehicle vehicle) {
        return vehicle.getType() == this.supportedType;
    }

    double calculateHourlyRate() {
        return 5.0; // base rate
    }
}

// NEW REQUIREMENT: Add EV charging support
class ChargingSpot extends ParkingSpot {
    private ChargingSpeed speed; // FAST, NORMAL

    boolean canAccommodate(Vehicle vehicle) {
        // Only electric vehicles, check charging port compatibility
        return vehicle instanceof ElectricVehicle ev 
            && ev.hasCompatiblePort(this.speed);
    }

    double calculateHourlyRate() {
        return 5.0 + (speed == ChargingSpeed.FAST ? 3.0 : 1.5);
    }
}

// No modification to StandardSpot or core allocation logic!

// Scenario: Storing parking spots for fast allocation

// Option 1: HashMap for O(1) lookup by ID
class ParkingLot {
    private Map<String, ParkingSpot> spotsById = new HashMap<>();

    ParkingSpot findSpotById(String id) {
        return spotsById.get(id); // O(1) lookup
    }

    // Trade-off: No ordering, hard to find "closest" spot
}

// Option 2: PriorityQueue for closest-first allocation
class ParkingLot {
    private Queue<ParkingSpot> spotsByDistance = new PriorityQueue<>(
        Comparator.comparingDouble(ParkingSpot::distanceFromEntrance)
    );

    ParkingSpot assignClosestSpot(VehicleType type) {
        return spotsByDistance.stream()
            .filter(s -> s.supportsType(type))
            .findFirst().orElse(null);
    }

    // Trade-off: O(log n) insertion, O(n) for filtering by type
}

// What to SAY in interview:
// "I'm choosing HashMap because spot lookup by ticket ID
// during exit will be frequent. If the requirement emphasized
// assigning the closest available spot, I'd use PriorityQueue
// ordered by distance. Let me know if closest-spot logic is critical."

// SRP: Split god class into focused classes
class ParkingLotManager {
    private SpotAllocator allocator;
    private PaymentProcessor paymentProcessor;

    Ticket parkVehicle(Vehicle v) {
        var spot = allocator.findSpot(v.getType()); // SRP: allocation delegated
        return new Ticket(spot, LocalDateTime.now());
    }
}

// OCP: New vehicle types extend without modifying allocation logic
abstract class Vehicle {
    abstract VehicleType getType();
}
class Motorcycle extends Vehicle { /* OCP: extend, don't modify */ }

// LSP: Subclasses must be substitutable
class HandicappedSpot extends ParkingSpot {
    boolean canAccommodate(Vehicle v) {
        // Must still return boolean, not throw exception
        return v.hasHandicappedPermit();
    }
}

// ISP: Focused interfaces, not one giant interface
interface Payable {
    double calculateFee();
}
interface Reservable {
    void reserve(Customer c, LocalDateTime time);
}
// Don't force all spots to implement both

// DIP: Depend on abstraction, not concrete class
class ParkingLotManager {
    private PaymentProcessor processor; // interface, not StripeProcessor

    void processPayment(Ticket t, PaymentMethod m) {
        processor.process(t, m); // DIP: can swap implementations
    }
}
